// The history and the chat side by side, as the web draws them. On a phone, use NavigationSplitView so the
// history is the column behind the back button.
HStack(spacing: 0) {
    NavigationStack {
    MonarchAiConversationList(
        conversations,
        activeID: activeID,
        now: now,
        onNew: {
            let id = "c\(conversations.count + 1)"
            conversations.insert(MonarchAiConversationSummary(id: id, title: "", updatedAt: now), at: 0)
            open(id)
        },
        onRename: { id, title in rename(id, to: title) },
        onPin: { id, isPinned in
            if let index = conversations.firstIndex(where: { $0.id == id }) { conversations[index].isPinned = isPinned }
        },
        onDelete: { id in conversations.removeAll { $0.id == id } },
        onSelect: { id in open(id) }
    )
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
    }
    .frame(width: 214)
    MonarchDivider()
    VStack(spacing: 0) {
        ViewThatFits(in: .horizontal) {
        HStack(spacing: theme.spacing.space2) {
            MonarchAiConversationHeader(
                title,
                agent: conversation.agent,
                onRename: { newTitle in
                    if let activeID { rename(activeID, to: newTitle) }
                }
            )
            Spacer(minLength: 0)
            MonarchButton("Show artifact", variant: .secondary, size: .sm) {}
        }
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            MonarchAiConversationHeader(
                title,
                agent: conversation.agent,
                onRename: { newTitle in
                    if let activeID { rename(activeID, to: newTitle) }
                }
            )
            MonarchButton("Show artifact", variant: .secondary, size: .sm) {}
        }
        }
        .padding(.horizontal, theme.spacing.space3)
        .padding(.vertical, theme.spacing.space2)
        MonarchDivider()
        MonarchAiThread(
            conversation.messages,
            status: conversation.status,
            error: conversation.error,
            isOffline: !conversation.isOnline,
            queuedCount: conversation.queued.count,
            isSlow: conversation.isSlow,
            onStop: { conversation.stop() },
            empty: {
                ScrollView {
                    MonarchAiWelcome({{welcome.title}}, agent: conversation.agent, description: {{welcome.description}}) {
                        MonarchAiStarterPrompts(starters, layout: .list) { starter in
                            conversation.send(starter.prompt)
                        }
                        .disabled(conversation.isBusy || !conversation.canSend)
                    }
                    .padding(theme.spacing.space3)
                }
            }
        )
        .safeAreaInset(edge: .bottom) {
            MonarchAiPromptInput(
                "Message the assistant",
                text: $prompt,
                isBusy: conversation.isBusy,
                onStop: { conversation.stop() },
                triggerMenu: { EmptyView() },
                toolbar: { EmptyView() },
                footer: { MonarchAiDisclaimer() },
                onSubmit: { text in
                    guard conversation.send(text) else { throw NotSent() }
                }
            )
            .padding(theme.spacing.space3)
        }
    }
}
.overlay(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous).stroke(theme.colors.borderSubtle))
.clipShape(RoundedRectangle(cornerRadius: theme.radius.lg, style: .continuous))
.dynamicTypeSize(.xSmall)
.frame(height: 640)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme

private struct EchoTransport: MonarchAiTransport {
    func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
        MonarchAiEventStream { continuation in
            continuation.yield(.textDelta("You asked: " + (request.messages.last?.text ?? "")))
            continuation.yield(.done())
            continuation.finish()
        }
    }
}

/// A send the conversation refused, so the prompt input gives the text back.
private struct NotSent: Error {}

private let now = Date(timeIntervalSince1970: 1_794_664_800)
private let starters = [
    MonarchAiStarterPrompt(id: {{starters.0.id}}, title: {{starters.0.title}}, prompt: {{starters.0.prompt}}),
    MonarchAiStarterPrompt(id: {{starters.1.id}}, title: {{starters.1.title}}, prompt: {{starters.1.prompt}}),
]

// One conversation object for the open chat; the app loads stored messages into it with reset.
@State private var conversation = MonarchAiConversation(transport: EchoTransport())
@State private var conversations = [
    MonarchAiConversationSummary(id: {{conversations.0.id}}, title: {{conversations.0.title}}, updatedAt: Date(timeIntervalSince1970: 1_794_660_000)),
    MonarchAiConversationSummary(
        id: {{conversations.1.id}},
        title: {{conversations.1.title}},
        updatedAt: Date(timeIntervalSince1970: 1_794_490_000),
        isPinned: {{conversations.1.pinned}}
    ),
    MonarchAiConversationSummary(id: {{conversations.2.id}}, title: {{conversations.2.title}}, updatedAt: Date(timeIntervalSince1970: 1_792_936_800)),
]
@State private var activeID: String? = {{activeId}}
@State private var prompt = ""

private var title: String { conversations.first { $0.id == activeID }?.title ?? "" }

private func open(_ id: String) {
    activeID = id
    conversation.reset()  // Pass the app's stored messages of id.
}

private func rename(_ id: String, to title: String) {
    if let index = conversations.firstIndex(where: { $0.id == id }) { conversations[index].title = title }
}

